import * as React from 'react';

// @interlace/milestones v1.1.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/milestones
// What changed since: https://ds.interlace.tools/c/milestones#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Milestones
 *
 * The marks along a path a player is on (a 3, 7 and 30-day streak; levels
 * 5, 10 and 20): the ones reached, the next one with how far is left, and
 * a few beyond. It shows where the player is going, not a wall of locked
 * trophies, so only a window around the next mark is drawn.
 *
 * ## Anatomy
 *
 *   Milestones                     (div — data-slot="milestones")
 *     ├─ ol                        (data-slot="milestones-list", labelled)
 *     │   └─ li × n                (data-slot="milestone", data-state=reached|next|ahead)
 *     │       ├─ span aria-hidden  (data-slot="milestone-mark": the step, an award when reached)
 *     │       └─ span              (data-slot="milestone-label")
 *     └─ p                         (data-slot="milestones-next": "3 more days to 7 days")
 *
 * ## Never colour alone
 *
 * Reached is a filled mark with an award icon, next a ring in the accent
 * with a dot, ahead a dashed ring. Each item also says its state in words
 * for assistive tech.
 *
 * ## Motion
 *
 * The latest reached mark scales in once (CSS `@starting-style`,
 * `motion-safe:` only). Renders on the server.
 *
 * ## MIN_VIEWPORT — 320
 *
 * Five marks fit a 288px column; the row wraps beyond that.
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `React.ComponentProps<'div'>`                        |
 * | R6   | data-slot per part        | milestones / -list / milestone / -mark / -label / -next |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R19  | Tokens only               | primary, input, muted-foreground                     |
 * | R26  | A11y                      | labelled list; every state in words                  |
 */

import { Award } from 'lucide-react';

import { cn } from '@/lib/utils';
import { nextMilestone } from '@/components/ui/games/progress-model';

export const MIN_VIEWPORT = 320 as const;

export type MilestoneState = 'reached' | 'next' | 'ahead';

interface MilestonesLabels {
  /** Names the list. @default 'Milestones' */
  list?: string;
  /** One step, as words: "7 days". @default n => n */
  step?: (step: number, formatted: string) => string;
  /** The line under the list. @default (left, step) => `${left} more to ${step}` */
  next?: (left: string, step: string) => string;
  /** When every step is reached. @default 'Every milestone reached.' */
  done?: string;
  /** Each state, read after the step. */
  state?: Partial<Record<MilestoneState, string>>;
}

type MilestonesProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  /** Where the player is: a streak length, a level. */
  value: number;
  /** The steps, any order. */
  steps: readonly number[];
  /** How many reached steps to keep in view. @default 2 */
  behind?: number;
  /** How many steps to show in all. @default 5 */
  show?: number;
  /** BCP 47 locale for the numbers. */
  locale?: string;
  labels?: MilestonesLabels;
};

const STATE: Record<MilestoneState, string> = { reached: 'reached', next: 'next', ahead: 'ahead' };

const MARK =
  'grid size-10 shrink-0 place-items-center rounded-full text-sm font-semibold tabular-nums [&_svg]:size-4';

/** The window of steps to draw: a few reached, the next, and some ahead. */
export function milestoneWindow(value: number, steps: readonly number[], behind = 2, show = 5): number[] {
  const sorted = [...new Set(steps)].sort((a, b) => a - b);
  const firstAhead = sorted.findIndex((s) => s > value);
  const pivot = firstAhead === -1 ? sorted.length : firstAhead;
  const count = Math.max(1, show);
  let start = Math.max(0, pivot - Math.max(0, behind));
  start = Math.max(0, Math.min(start, sorted.length - count));
  return sorted.slice(start, start + count);
}

function Milestones({
  value,
  steps,
  behind = 2,
  show = 5,
  locale,
  labels,
  className,
  ...props
}: MilestonesProps) {
  const nf = new Intl.NumberFormat(locale);
  const shown = milestoneWindow(value, steps, behind, show);
  const next = nextMilestone(value, steps);
  const lastReached = [...shown].reverse().find((s) => s <= value);
  const word = (s: number) => (labels?.step ?? ((_n: number, f: string) => f))(s, nf.format(s));

  return (
    <div
      data-slot="milestones"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-3', className)}
      {...props}
    >
      <ol
        data-slot="milestones-list"
        aria-label={labels?.list ?? 'Milestones'}
        className="flex flex-wrap gap-x-3 gap-y-2"
      >
        {shown.map((s) => {
          const state: MilestoneState = s <= value ? 'reached' : s === next ? 'next' : 'ahead';
          return (
            <li
              key={s}
              data-slot="milestone"
              data-state={state}
              aria-current={state === 'next' ? 'step' : undefined}
              className="grid w-14 justify-items-center gap-1 text-center"
            >
              <span
                aria-hidden
                data-slot="milestone-mark"
                className={cn(
                  MARK,
                  state === 'reached' && 'bg-primary text-primary-foreground',
                  state === 'next' && 'border-primary text-foreground border-2',
                  state === 'ahead' && 'border-input text-muted-foreground border-2 border-dashed',
                  s === lastReached &&
                    'motion-safe:transition-[scale,opacity] motion-safe:duration-(--duration-medium) motion-safe:ease-enter motion-safe:starting:scale-75 motion-safe:starting:opacity-0',
                )}
              >
                {state === 'reached' ? <Award /> : nf.format(s)}
              </span>
              <span
                data-slot="milestone-label"
                className={cn('text-xs leading-tight', state === 'ahead' ? 'text-muted-foreground' : 'font-medium')}
              >
                {word(s)}
                <span className="sr-only">: {labels?.state?.[state] ?? STATE[state]}</span>
              </span>
            </li>
          );
        })}
      </ol>
      <p data-slot="milestones-next" dir="auto" className="text-muted-foreground text-sm tabular-nums">
        {next === undefined
          ? (labels?.done ?? 'Every milestone reached.')
          : (labels?.next ?? ((l: string, s: string) => `${l} more to ${s}`))(nf.format(next - value), word(next))}
      </p>
    </div>
  );
}
Milestones.displayName = 'Milestones';

export { Milestones };
export type { MilestonesProps, MilestonesLabels };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */

import { isDayKey, type DayKey } from '@/components/ui/games/daily';

/**
 * @interlace/ui — games/progress-model
 *
 * The numbers behind a sense of progress: experience points (XP) and the
 * level they add up to, a daily goal, and milestones worth marking. Pure:
 * give it what the player earned and on which day; it returns where they
 * stand. A game decides what earns XP; this file only adds it up, so a
 * server can check the same numbers a screen shows.
 *
 * ## XP rewards showing up
 *
 * A game that pays for "right" teaches people to say they were right. Give
 * XP for finishing things, and keep honest self-ratings out of it.
 *
 * ## Levels
 *
 * Level 1 starts at 0 XP. Each level costs `first + step × (level − 1)` XP
 * to finish (100, 150, 200… by default), so early levels come quickly and
 * later ones stay within reach.
 *
 * ## Daily goal
 *
 * The XP a player means to earn each day. `goalOn` says how far today is;
 * `goalDays` lists the days the goal was met, which `summarizeStreak` can
 * turn into a goal streak.
 *
 * ## Milestones
 *
 * A milestone is a value worth marking (a 7-day streak, level 5).
 * `milestonesCrossed` returns the ones a change passed, so a screen
 * celebrates each once, at the moment it happens, and never on a reload.
 */

/** XP earned on one day. Several entries for the same day add up. */
export interface XpEntry {
  day: DayKey;
  xp: number;
}

export interface LevelCurve {
  /** XP to finish level 1. @default 100 */
  first: number;
  /** Extra XP each later level costs. @default 50 */
  step: number;
}

export const DEFAULT_LEVEL_CURVE: LevelCurve = { first: 100, step: 50 };

export interface Level {
  /** 1-based. */
  level: number;
  /** XP earned inside this level. */
  into: number;
  /** XP this level takes to finish. */
  span: number;
  /** `into / span`, 0 to 1. */
  progress: number;
  /** XP still needed for the next level. */
  toNext: number;
  /** All XP, the input. */
  total: number;
}

const clean = (xp: number) => (Number.isFinite(xp) && xp > 0 ? xp : 0);

function curveOf(curve?: Partial<LevelCurve>): LevelCurve {
  const first = clean(curve?.first ?? DEFAULT_LEVEL_CURVE.first) || DEFAULT_LEVEL_CURVE.first;
  const step = clean(curve?.step ?? DEFAULT_LEVEL_CURVE.step);
  return { first, step };
}

/** XP to finish `level` (1-based) on this curve. */
export function levelSpan(level: number, curve?: Partial<LevelCurve>): number {
  const c = curveOf(curve);
  return c.first + c.step * (Math.max(1, Math.floor(level)) - 1);
}

/** The level a total of XP reaches, and how far into it. */
export function levelFor(totalXp: number, curve?: Partial<LevelCurve>): Level {
  const total = clean(totalXp);
  let level = 1;
  let left = total;
  let span = levelSpan(1, curve);
  while (left >= span) {
    left -= span;
    level += 1;
    span = levelSpan(level, curve);
  }
  return { level, into: left, span, progress: left / span, toNext: span - left, total };
}

/** Every valid entry's XP, added up. */
export function totalXp(entries: Iterable<XpEntry>): number {
  let sum = 0;
  for (const e of entries) if (isDayKey(e.day)) sum += clean(e.xp);
  return sum;
}

/** XP earned on one day. */
export function xpOn(entries: Iterable<XpEntry>, day: DayKey): number {
  let sum = 0;
  for (const e of entries) if (e.day === day) sum += clean(e.xp);
  return sum;
}

export interface GoalProgress {
  earned: number;
  goal: number;
  met: boolean;
  /** 0 to 1, capped at 1. */
  progress: number;
  /** XP still needed today; 0 once met. */
  left: number;
}

/** How far a day is toward the goal. A goal of 0 or less counts as met. */
export function goalOn(entries: Iterable<XpEntry>, day: DayKey, goal: number): GoalProgress {
  const earned = xpOn(entries, day);
  const g = clean(goal);
  if (g === 0) return { earned, goal: 0, met: true, progress: 1, left: 0 };
  return { earned, goal: g, met: earned >= g, progress: Math.min(1, earned / g), left: Math.max(0, g - earned) };
}

/** The days the goal was met, sorted. Feed them to `summarizeStreak` for a goal streak. */
export function goalDays(entries: Iterable<XpEntry>, goal: number): DayKey[] {
  const byDay = new Map<DayKey, number>();
  for (const e of entries) if (isDayKey(e.day)) byDay.set(e.day, (byDay.get(e.day) ?? 0) + clean(e.xp));
  const g = clean(goal);
  return [...byDay].filter(([, xp]) => xp > 0 && xp >= g).map(([day]) => day).sort();
}

/** Streak lengths worth marking. */
export const DEFAULT_STREAK_MILESTONES: readonly number[] = [3, 7, 14, 30, 50, 100, 200, 365];

/** The milestones a change from `before` to `after` passed, smallest first. */
export function milestonesCrossed(before: number, after: number, steps: readonly number[]): number[] {
  return [...steps].filter((s) => s > before && s <= after).sort((a, b) => a - b);
}

/** The first milestone above `value`, or undefined past the last. */
export function nextMilestone(value: number, steps: readonly number[]): number | undefined {
  return [...steps].sort((a, b) => a - b).find((s) => s > value);
}

/** The highest milestone reached, or undefined before the first. */
export function lastMilestone(value: number, steps: readonly number[]): number | undefined {
  return [...steps].sort((a, b) => b - a).find((s) => s <= value);
}

export interface XpGain {
  before: Level;
  after: Level;
  gained: number;
  /** Levels finished by this gain (0 most of the time). */
  levelsUp: number;
}

/** What one gain did: the level before and after, and how many levels it finished. */
export function gainXp(totalBefore: number, gained: number, curve?: Partial<LevelCurve>): XpGain {
  const before = levelFor(totalBefore, curve);
  const g = clean(gained);
  const after = levelFor(before.total + g, curve);
  return { before, after, gained: g, levelsUp: after.level - before.level };
}
